<script setup>
import {ref,onMounted} from 'vue';import {api} from '../api'
const data=ref({items:[],page:0,size:20,total:0}),status=ref(''),error=ref('');const labels={UNASSESSED:'未评估',INSUFFICIENT:'证据不足',WEAK:'待加强',CONSOLIDATE:'巩固',STABLE:'稳定'}
const score=v=>v==null?'—':Number(v).toFixed(1);const date=v=>v?new Date(v).toLocaleString():'—'
async function load(page=0){try{error.value='';data.value=await api(`/api/review/mastery?page=${page}&size=20${status.value?'&status='+status.value:''}`)}catch(e){error.value=e.message}}
onMounted(()=>load())
</script>
<template><div class="practice-shell"><header class="practice-top"><div><span class="practice-kicker">MASTERY</span><h1 class="practice-title">知识点掌握度</h1></div><RouterLink to="/">返回首页</RouterLink></header><div class="p-card"><div class="p-actions"><label>状态 <select v-model="status" @change="load(0)"><option value="">全部</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><button class="p-secondary" @click="load(data.page)">刷新</button></div><p v-if="error" class="p-error">{{error}}</p><table class="p-table"><thead><tr><th>知识点</th><th>最终分</th><th>规则分</th><th>n</th><th>状态</th><th>最近练习</th><th>更新状态</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.knowledgeId"><td><RouterLink :to="`/mastery/${item.knowledgeId}`">{{item.knowledgeCode}} {{item.knowledgeName}}</RouterLink><small>{{item.chapterTitle}}</small></td><td>{{score(item.finalScore)}}</td><td>{{score(item.ruleScore)}}</td><td>{{item.n}}</td><td>{{labels[item.status]}}</td><td>{{date(item.latestPracticeAt)}}</td><td>{{item.updating?'更新中':'已更新'}}</td></tr></tbody></table><div class="p-actions"><button class="p-secondary" :disabled="data.page===0" @click="load(data.page-1)">上一页</button><span>第 {{data.page+1}} 页</span><button class="p-secondary" :disabled="(data.page+1)*data.size>=data.total" @click="load(data.page+1)">下一页</button></div></div></div></template>
<style scoped>small{display:block;color:#666}select{padding:8px;background:white;border:1px solid #aaa}table{margin:16px 0}</style>
